package dev.tiertagger.core;
public record ProviderStatus(State state,String reason) {
 public enum State { NOT_CHECKED,CHECKING,CONNECTED,ERROR }
 public String label(){return switch(state){case NOT_CHECKED->"Not checked";case CHECKING->"Checking...";case CONNECTED->"Connected";case ERROR->"Error: "+reason;};}
 public static ProviderStatus http(int code){return new ProviderStatus(State.ERROR,code==429?"Rate limited (HTTP 429)":code>=500?"Request failed (HTTP "+code+")":"HTTP "+code);}
 public static ProviderStatus failure(Throwable error){String reason;if(error instanceof java.net.http.HttpTimeoutException)reason="Request timed out";else if(error instanceof java.net.ConnectException||error instanceof java.net.UnknownHostException)reason="Cannot reach API";else if(error instanceof IllegalArgumentException||error instanceof com.google.gson.JsonParseException)reason="Invalid API response";else if(error.getMessage()!=null&&error.getMessage().startsWith("HTTP ")){try{return http(Integer.parseInt(error.getMessage().substring(5)));}catch(NumberFormatException ex){reason="Request failed";}}else reason="Request failed";return new ProviderStatus(State.ERROR,reason);}
 public static ProviderStatus fromLegacy(String raw){String s=raw.toLowerCase(java.util.Locale.ROOT);if(s.contains("connected")||s.equals("available"))return new ProviderStatus(State.CONNECTED,"");if(s.contains("checking"))return new ProviderStatus(State.CHECKING,"");if(s.contains("waiting")||s.contains("not checked"))return new ProviderStatus(State.NOT_CHECKED,"");return new ProviderStatus(State.ERROR,raw.startsWith("Error: ")?raw.substring(7):raw);}
}
